using Dapper;
using System.ComponentModel.DataAnnotations;
using Valora.Application.Contracts;
using Valora.Application.SolutionPacks;

namespace Valora.Infrastructure.SolutionPacks;

public sealed class SolutionPackRepository(IDbConnectionFactory factory) : ISolutionPackRepository
{
    private const string Summary="p.id Id,p.organization_id OrganizationId,p.name Name,p.description Description,p.category Category,p.segment Segment,p.status Status,p.is_official IsOfficial,v.version_number CurrentVersion,p.updated_at UpdatedAt";
    public async Task<IReadOnlyList<SolutionPackSummary>> ListAsync(Guid organizationId,string? segment,string? category,CancellationToken ct){using var c=factory.Create();var sql=$"""SELECT {Summary} FROM valorapesquisa.solution_packs p LEFT JOIN LATERAL (SELECT version_number FROM valorapesquisa.solution_pack_versions WHERE solution_pack_id=p.id AND status='published' ORDER BY created_at DESC LIMIT 1) v ON true WHERE p.deleted_at IS NULL AND (p.is_official OR p.organization_id=@organizationId) AND (@segment IS NULL OR p.segment=@segment) AND (@category IS NULL OR p.category=@category) ORDER BY p.is_official DESC,p.name""";return(await c.QueryAsync<SolutionPackSummary>(new CommandDefinition(sql,new{organizationId,segment=Blank(segment),category=Blank(category)},cancellationToken:ct))).AsList();}
    public async Task<SolutionPackDetails?> GetAsync(Guid id,Guid organizationId,CancellationToken ct){using var c=factory.Create();var sql=$"""SELECT {Summary},p.evidence Evidence FROM valorapesquisa.solution_packs p LEFT JOIN LATERAL (SELECT version_number FROM valorapesquisa.solution_pack_versions WHERE solution_pack_id=p.id ORDER BY created_at DESC LIMIT 1) v ON true WHERE p.id=@id AND p.deleted_at IS NULL AND (p.is_official OR p.organization_id=@organizationId)""";var row=await c.QuerySingleOrDefaultAsync<DetailRow>(new CommandDefinition(sql,new{id,organizationId},cancellationToken:ct));if(row is null)return null;var items=(await c.QueryAsync<SolutionPackItemDto>(new CommandDefinition("SELECT i.id Id,i.item_type ItemType,i.name Name,i.source_module SourceModule,i.source_template_id SourceTemplateId,i.metadata_json::text MetadataJson FROM valorapesquisa.solution_pack_items i JOIN valorapesquisa.solution_pack_versions v ON v.id=i.solution_pack_version_id WHERE v.solution_pack_id=@id AND i.deleted_at IS NULL ORDER BY i.created_at",new{id},cancellationToken:ct))).AsList();var deps=(await c.QueryAsync<SolutionPackDependencyDto>(new CommandDefinition("SELECT d.id Id,d.dependency_type DependencyType,d.required_module RequiredModule,d.required_permission RequiredPermission,d.minimum_version MinimumVersion FROM valorapesquisa.solution_pack_dependencies d WHERE d.solution_pack_id=@id ORDER BY d.created_at",new{id},cancellationToken:ct))).AsList();return new(row.Id,row.OrganizationId,row.Name,row.Description,row.Category,row.Segment,row.Status,row.IsOfficial,row.CurrentVersion,row.Evidence,items,deps);}
    public async Task<Guid> CreateAsync(Guid id,Guid organizationId,Guid actor,CreateSolutionPackRequest r,CancellationToken ct){using var c=factory.Create();const string sql="""INSERT INTO valorapesquisa.solution_packs(id,organization_id,name,description,category,segment,status,is_official,evidence,created_by) VALUES(@id,@organizationId,@Name,@Description,@Category,@Segment,'draft',@IsOfficial,@Evidence,@actor)""";await c.ExecuteAsync(new CommandDefinition(sql,new{id,organizationId,actor,r.Name,r.Description,r.Category,r.Segment,r.IsOfficial,r.Evidence},cancellationToken:ct));return id;}
    public async Task<Guid> CreateVersionAsync(Guid packId,Guid organizationId,Guid actor,NewVersionRequest r,CancellationToken ct){using var c=factory.Create();c.Open();using var tx=c.BeginTransaction();var versionId=Guid.NewGuid();const string version="""INSERT INTO valorapesquisa.solution_pack_versions(id,solution_pack_id,version_number,status,release_notes,created_by) SELECT @versionId,id,@VersionNumber,'draft',@ReleaseNotes,@actor FROM valorapesquisa.solution_packs WHERE id=@packId AND (organization_id=@organizationId OR is_official) AND status<>'archived' RETURNING id""";var created=await c.QuerySingleOrDefaultAsync<Guid?>(new CommandDefinition(version,new{versionId,packId,organizationId,actor,r.VersionNumber,r.ReleaseNotes},tx,cancellationToken:ct))??throw new ValidationException("Pacote indisponível para versionamento.");foreach(var item in r.Items)await c.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.solution_pack_items(id,solution_pack_version_id,item_type,name,source_module,source_template_id,metadata_json) VALUES(gen_random_uuid(),@created,@ItemType,@Name,@SourceModule,@SourceTemplateId,CAST(COALESCE(@MetadataJson,'{}') AS jsonb))",new{created,item.ItemType,item.Name,item.SourceModule,item.SourceTemplateId,item.MetadataJson},tx,cancellationToken:ct));foreach(var d in r.Dependencies)await c.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.solution_pack_dependencies(id,solution_pack_id,dependency_type,required_module,required_permission,minimum_version) VALUES(gen_random_uuid(),@packId,@DependencyType,@RequiredModule,@RequiredPermission,@MinimumVersion)",new{packId,d.DependencyType,d.RequiredModule,d.RequiredPermission,d.MinimumVersion},tx,cancellationToken:ct));await Audit(c,tx,organizationId,packId,actor,"solution_pack.version.created",new{versionId,r.VersionNumber},ct);tx.Commit();return created;}
    public async Task<bool> PublishAsync(Guid packId,Guid organizationId,Guid actor,CancellationToken ct){using var c=factory.Create();c.Open();using var tx=c.BeginTransaction();const string sql="""WITH latest AS (SELECT v.id FROM valorapesquisa.solution_pack_versions v JOIN valorapesquisa.solution_packs p ON p.id=v.solution_pack_id WHERE p.id=@packId AND (p.organization_id=@organizationId OR p.is_official) AND v.status='draft' ORDER BY v.created_at DESC LIMIT 1) UPDATE valorapesquisa.solution_pack_versions SET status='published',published_at=now() WHERE id=(SELECT id FROM latest)""";var changed=await c.ExecuteAsync(new CommandDefinition(sql,new{packId,organizationId},tx,cancellationToken:ct))==1;if(changed){await c.ExecuteAsync(new CommandDefinition("UPDATE valorapesquisa.solution_packs SET status='published',updated_at=now() WHERE id=@packId",new{packId},tx,cancellationToken:ct));await Audit(c,tx,organizationId,packId,actor,"solution_pack.published",new{},ct);}tx.Commit();return changed;}
    public async Task<InstallationPreview?> PreviewAsync(Guid packId,Guid organizationId,Guid? versionId,CancellationToken ct){using var c=factory.Create();const string vsql="""SELECT v.id Id,v.version_number VersionNumber FROM valorapesquisa.solution_pack_versions v JOIN valorapesquisa.solution_packs p ON p.id=v.solution_pack_id WHERE p.id=@packId AND p.status NOT IN ('archived','draft') AND (p.is_official OR p.organization_id=@organizationId) AND v.status='published' AND (@versionId IS NULL OR v.id=@versionId) ORDER BY v.published_at DESC LIMIT 1""";var v=await c.QuerySingleOrDefaultAsync<VersionRow>(new CommandDefinition(vsql,new{packId,organizationId,versionId},cancellationToken:ct));if(v is null)return null;var items=(await c.QueryAsync<SolutionPackItemDto>(new CommandDefinition("SELECT id Id,item_type ItemType,name Name,source_module SourceModule,source_template_id SourceTemplateId,metadata_json::text MetadataJson FROM valorapesquisa.solution_pack_items WHERE solution_pack_version_id=@id AND deleted_at IS NULL ORDER BY created_at",new{id=v.Id},cancellationToken:ct))).AsList();const string missing="""SELECT d.id Id,d.dependency_type DependencyType,d.required_module RequiredModule,d.required_permission RequiredPermission,d.minimum_version MinimumVersion FROM valorapesquisa.solution_pack_dependencies d WHERE d.solution_pack_id=@packId AND ((d.required_module IS NOT NULL AND NOT EXISTS(SELECT 1 FROM valorapesquisa.organization_modules m WHERE m.organization_id=@organizationId AND m.module_code=d.required_module AND m.enabled)) OR (d.required_permission IS NOT NULL AND NOT EXISTS(SELECT 1 FROM valorapesquisa.permissions p WHERE p.code=d.required_permission)))""";var deps=(await c.QueryAsync<SolutionPackDependencyDto>(new CommandDefinition(missing,new{packId,organizationId},cancellationToken:ct))).AsList();return new(packId,v.VersionNumber,items,deps,false,deps.Count==0);}
    public async Task<Guid> InstallAsync(Guid installationId,Guid packId,Guid organizationId,Guid actor,InstallSolutionPackRequest r,CancellationToken ct){using var c=factory.Create();c.Open();using var tx=c.BeginTransaction();const string sql="""INSERT INTO valorapesquisa.solution_pack_installations(id,organization_id,solution_pack_id,solution_pack_version_id,status,installed_by,installed_at,can_rollback) SELECT @installationId,@organizationId,@packId,v.id,'installed',@actor,now(),true FROM valorapesquisa.solution_pack_versions v JOIN valorapesquisa.solution_packs p ON p.id=v.solution_pack_id WHERE v.id=@VersionId AND p.id=@packId AND p.status NOT IN ('archived','draft') AND v.status='published'""";if(await c.ExecuteAsync(new CommandDefinition(sql,new{installationId,organizationId,packId,actor,r.VersionId},tx,cancellationToken:ct))!=1)throw new ValidationException("A versão publicada não está disponível.");await c.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.solution_pack_installation_items(id,installation_id,solution_pack_item_id,status) SELECT gen_random_uuid(),@installationId,i.id,'created' FROM valorapesquisa.solution_pack_items i WHERE i.solution_pack_version_id=@VersionId",new{installationId,r.VersionId},tx,cancellationToken:ct));await Audit(c,tx,organizationId,packId,actor,"solution_pack.installed",new{installationId,r.VersionId},ct);tx.Commit();return installationId;}
    public async Task<bool> RollbackAsync(Guid installationId,Guid organizationId,Guid actor,CancellationToken ct){using var c=factory.Create();c.Open();using var tx=c.BeginTransaction();const string sql="UPDATE valorapesquisa.solution_pack_installations SET status='rolled_back',rolled_back_at=now(),can_rollback=false,updated_at=now() WHERE id=@installationId AND organization_id=@organizationId AND status='installed' AND can_rollback";var changed=await c.ExecuteAsync(new CommandDefinition(sql,new{installationId,organizationId},tx,cancellationToken:ct))==1;if(changed){await c.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.solution_pack_rollbacks(id,installation_id,organization_id,requested_by,status,completed_at) VALUES(gen_random_uuid(),@installationId,@organizationId,@actor,'completed',now())",new{installationId,organizationId,actor},tx,cancellationToken:ct));await Audit(c,tx,organizationId,installationId,actor,"solution_pack.rolled_back",new{},ct);}tx.Commit();return changed;}
    public async Task<IReadOnlyList<InstallationDto>> InstallationsAsync(Guid organizationId,CancellationToken ct){using var c=factory.Create();const string sql="""SELECT i.id Id,i.organization_id OrganizationId,i.solution_pack_id SolutionPackId,p.name PackName,v.version_number VersionNumber,i.status Status,i.can_rollback CanRollback,i.installed_at InstalledAt FROM valorapesquisa.solution_pack_installations i JOIN valorapesquisa.solution_packs p ON p.id=i.solution_pack_id JOIN valorapesquisa.solution_pack_versions v ON v.id=i.solution_pack_version_id WHERE i.organization_id=@organizationId ORDER BY i.installed_at DESC""";return(await c.QueryAsync<InstallationDto>(new CommandDefinition(sql,new{organizationId},cancellationToken:ct))).AsList();}
    public async Task<IReadOnlyList<UpdateDto>> UpdatesAsync(Guid organizationId,CancellationToken ct){using var c=factory.Create();const string sql="""SELECT i.id InstallationId,p.id SolutionPackId,p.name PackName,installed.version_number InstalledVersion,available.version_number AvailableVersion FROM valorapesquisa.solution_pack_installations i JOIN valorapesquisa.solution_packs p ON p.id=i.solution_pack_id JOIN valorapesquisa.solution_pack_versions installed ON installed.id=i.solution_pack_version_id JOIN LATERAL(SELECT version_number FROM valorapesquisa.solution_pack_versions WHERE solution_pack_id=p.id AND status='published' ORDER BY published_at DESC LIMIT 1) available ON true WHERE i.organization_id=@organizationId AND i.status='installed' AND available.version_number<>installed.version_number""";return(await c.QueryAsync<UpdateDto>(new CommandDefinition(sql,new{organizationId},cancellationToken:ct))).AsList();}
    private static async Task Audit(System.Data.IDbConnection c,System.Data.IDbTransaction tx,Guid organizationId,Guid target,Guid actor,string action,object data,CancellationToken ct)=>await c.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.solution_pack_audit_events(id,organization_id,actor_user_id,event_type,target_id,metadata_json) VALUES(gen_random_uuid(),@organizationId,@actor,@action,@target,CAST(@json AS jsonb))",new{organizationId,actor,action,target,json=System.Text.Json.JsonSerializer.Serialize(data)},tx,cancellationToken:ct));
    private static string? Blank(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();
    private sealed record DetailRow(Guid Id,Guid? OrganizationId,string Name,string Description,string Category,string Segment,string Status,bool IsOfficial,string? CurrentVersion,string? Evidence);
    private sealed record VersionRow(Guid Id,string VersionNumber);
}
